using namespace std;

class Solution {
public:
    int numberOfRounds(string loginTime, string logoutTime) {
        int h1 = stoi(loginTime.substr(0, 2)), m1 = stoi(loginTime.substr(3, 2));
        int h2 = stoi(logoutTime.substr(0, 2)), m2 = stoi(logoutTime.substr(3, 2));
        int t1 = h1 * 60 + m1;
        int t2 = h2 * 60 + m2;

        if (t2 < t1) {
            t2 += 24 * 60;
        }

        int start = ((t1 + 14) / 15) * 15;
        int end = (t2 / 15) * 15;

        if (end < start) return 0;
        return (end - start) / 15;
    }
};

class Solution {
    public int numberOfRounds(String loginTime, String logoutTime) {
        int h1 = Integer.parseInt(loginTime.substring(0, 2));
        int m1 = Integer.parseInt(loginTime.substring(3, 5));
        int h2 = Integer.parseInt(logoutTime.substring(0, 2));
        int m2 = Integer.parseInt(logoutTime.substring(3, 5));
        int t1 = h1 * 60 + m1;
        int t2 = h2 * 60 + m2;

        if (t2 < t1) {
            t2 += 24 * 60;
        }

        int start = ((t1 + 14) / 15) * 15;
        int end = (t2 / 15) * 15;

        if (end < start) return 0;
        return (end - start) / 15;
    }
}

/**
 * @param {string} loginTime
 * @param {string} logoutTime
 * @return {number}
 */
var numberOfRounds = function(loginTime, logoutTime) {
    const h1 = parseInt(loginTime.slice(0, 2), 10);
    const m1 = parseInt(loginTime.slice(3, 5), 10);
    const h2 = parseInt(logoutTime.slice(0, 2), 10);
    const m2 = parseInt(logoutTime.slice(3, 5), 10);
    let t1 = h1 * 60 + m1;
    let t2 = h2 * 60 + m2;

    if (t2 < t1) {
        t2 += 24 * 60;
    }

    const start = Math.floor((t1 + 14) / 15) * 15;
    const end = Math.floor(t2 / 15) * 15;

    if (end < start) return 0;
    return Math.floor((end - start) / 15);
};
